def octal_To_Decimal(n):
    """Write a python function to convert octal number to decimal number."""
    if isinstance(n, bool):
        raise TypeError("octal number must be an int or str")
    if isinstance(n, int):
        text = str(n)
    elif isinstance(n, str):
        text = n.strip()
        if not text:
            raise ValueError("empty string is not a valid octal number")
    else:
        raise TypeError("octal number must be an int or str")

    sign = 1
    if text[:1] in ("+", "-"):
        if text[0] == "-":
            sign = -1
        text = text[1:]
        if not text:
            raise ValueError(f"invalid octal number: {n!r}")

    if text.lower().startswith("0o"):
        text = text[2:]

    if not text or any(ch not in "01234567" for ch in text):
        raise ValueError(f"invalid octal number: {n!r}")

    decimal = 0
    for ch in text:
        decimal = decimal * 8 + int(ch)
    return sign * decimal
